import { useParams } from "react-router-dom";
import { Project, projects } from "../data/projects";
import { Border, Container, FlexBox } from "../components";
import { Typography, useTheme } from "@mui/material";

export const ProjectDetail = () => {
  const theme = useTheme();
  const { slug } = useParams<{ slug: string }>();

  const project: Project | undefined = projects.find(
    (project) => project.slug === slug
  );

  if (!project) return <div>Project not found</div>;

  return (
    <Container
      id="projectDetail"
      backgroundImage="url('background-1.jpg')"
    >
      <Border
        style={{
          marginTop: theme.spacing(5),
        }}
      >
        <FlexBox flexDirection="column" gap={1}>
          <Typography variant="h2" color="red">{project.title}</Typography>
          <Typography variant="body1" color="red">{project.description}</Typography>
          <Typography variant="body1" color="red">{project.year}</Typography>
          <Typography variant="body1" color="red">{project.role}</Typography>
          {
            project.technologies.map((technology) => (
              <Typography variant="body1" color="red">{technology}</Typography>
            ))
          }
          {project.images.map((image, index) => (
            <img key={index} src={image} alt={`${project.title} ${index + 1}`} />
          ))}
        </FlexBox>
      </Border>
    </Container>
  );
};